package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TextBuffer.contentsAsDecimal()
 * Designed to maximize branch and line coverage.
 */
public class TextBuffer_contentsAsDecimal_TriageGen0Test {

    private BufferRecycler _recycler;
    private TextBuffer _textBuffer;

    @Before
    public void setUp() {
        _recycler = new BufferRecycler();
        _textBuffer = new TextBuffer(_recycler);
    }

    /**
     * Tests the branch: if (_segmentSize == 0)
     * This is the "usual case" where we use the current segment.
     */
    @Test
    public void testContentsAsDecimal_UsingCurrentSegment() {
        _textBuffer.append("123.45");
        BigDecimal expected = new BigDecimal("123.45");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    /**
     * Tests the branch: if (_inputStart >= 0)
     * This simulates a shared buffer scenario.
     */
    @Test
    public void testContentsAsDecimal_UsingSharedBuffer() {
        char[] sharedBuf = "987.65".toCharArray();
        // resetWithShared sets _inputStart and _inputLen
        _textBuffer.resetWithShared(sharedBuf, 0, sharedBuf.length);

        BigDecimal expected = new BigDecimal("987.65");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    /**
     * Tests the branch: if (_resultArray != null)
     * Note: In the provided source, _resultArray is not directly settable via public API.
     * However, in Jackson's TextBuffer, this occurs during specific internal parsing states.
     * Since we cannot easily trigger the private _resultArray field without reflection 
     * or internal knowledge of how Jackson sets it, we simulate the logic paths 
     * available through the public API.
     * 
     * If we cannot reach the _resultArray branch via public methods in this specific context,
     * we ensure all other branches are hit.
     */

    /**
     * Tests the branch: return NumberInput.parseBigDecimal(contentsAsArray());
     * This happens when _resultArray == null, _inputStart < 0, and _segmentSize != 0.
     * This occurs when segments have been finished/aggregated.
     */
    @Test
    public void testContentsAsDecimal_UsingAggregatedArray() {
        _textBuffer.append("1");
        _textBuffer.finishCurrentSegment(); // This makes segmentSize != 0 in some versions or triggers aggregation logic
        _textBuffer.append("23.45");

        // When segments are finished, the buffer aggregates them into an array.
        BigDecimal expected = new BigDecimal("123.45");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    /**
     * Tests that invalid numeric strings throw NumberFormatException.
     */
    @Test(expected = NumberFormatException.class)
    public void testContentsAsDecimal_InvalidFormat() {
        _textBuffer.append("not_a_number");
        _textBuffer.contentsAsDecimal();
    }

    /**
     * Tests edge case: Empty buffer.
     */
    @Test(expected = NumberFormatException.class)
    public void testContentsAsDecimal_Empty() {
        _textBuffer.resetWithEmpty();
        _textBuffer.contentsAsDecimal();
    }

    /**
     * Tests large precision/scale.
     */
    @Test
    public void testContentsAsDecimal_LargePrecision() {
        String largeVal = "12345678901234567890.1234567890";
        _textBuffer.resetWithString(largeVal);
        BigDecimal expected = new BigDecimal(largeVal);
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }
}
